def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line - add the last field if we were building one
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - represents a single quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check that it's followed by comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        fields.append(''.join(field))
                        if i < n:
                            i += 1  # Skip the comma
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < n:
                i += 1  # Skip the comma

    return fields

